import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 이미 마감된 거래는 대상 결의서의 결재 상태가 '완료'인 경우로 본다.
const CLOSED_APPROVAL_STATUS = '완료';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function toId(v: unknown): string | null {
  if (typeof v === 'number' && Number.isInteger(v) && v > 0) {
    return String(v);
  }
  if (typeof v === 'string' && /^[0-9]+$/.test(v.trim())) {
    return v.trim();
  }
  return null;
}

@Controller('api/v1')
export class FnSfr00406Controller {
  @Post('/account-substitutions')
  @HttpCode(200)
  async createAccountSubstitution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const resolutionId = toId(data['expenseResolutionId']);
    const accountId = toId(data['partnerAccountId']);
    const reasonRaw = data['substitutionReason'];
    const reason = typeof reasonRaw === 'string' ? reasonRaw.trim() : '';
    if (resolutionId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 결의서를 선택해 주세요.');
    }
    if (accountId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대체 계좌를 선택해 주세요.');
    }
    if (reason === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '대체 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const resolutions = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: resolutionId },
      );
      if (resolutions.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '대상 결의서를 찾을 수 없습니다.');
      }
      if (resolutions[0]['approvalStatus'] === CLOSED_APPROVAL_STATUS) {
        throw new ApiError(409, 'TRANSACTION_ALREADY_CLOSED', '이미 마감된 거래입니다. 마감취소 절차를 먼저 진행해 주세요.');
      }
      const accounts = await db.query(
        'SELECT partner_account_id FROM partner_account WHERE partner_account_id = CAST(:id AS bigint)',
        { id: accountId },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '대체 계좌를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO account_substitution (expense_resolution_id, partner_account_id, substitution_reason, created_at, updated_at) VALUES (CAST(:resolutionId AS bigint), CAST(:accountId AS bigint), :reason, now(), now()) RETURNING account_substitution_id AS "accountSubstitutionId"',
        { resolutionId, accountId, reason },
      );
      return { accountSubstitutionId: Number(rows[0]['accountSubstitutionId']) };
    });
  }

  @Get('/account-substitutions')
  async listAccountSubstitutions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const pageNum = Number(query['page'] ?? 0);
    const sizeNum = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(sizeNum) || sizeNum < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 쪽 크기가 올바르지 않습니다.');
    }
    const page = pageNum;
    const size = Math.min(sizeNum, MAX_SIZE);
    const rawFilter = query['expenseResolutionId'];
    const hasFilter = rawFilter !== undefined && rawFilter !== null && rawFilter !== '';
    const resolutionId = hasFilter ? toId(rawFilter) : null;
    if (hasFilter && resolutionId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 결의서 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = resolutionId === null ? '' : ' WHERE expense_resolution_id = CAST(:resolutionId AS bigint)';
      const params: Record<string, unknown> = resolutionId === null ? {} : { resolutionId };
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM account_substitution' + where, params);
      const items = await db.query(
        'SELECT account_substitution_id AS "accountSubstitutionId", expense_resolution_id AS "expenseResolutionId", partner_account_id AS "partnerAccountId", substitution_reason AS "substitutionReason" FROM account_substitution' + where + ' ORDER BY account_substitution_id DESC LIMIT :size OFFSET :offset',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

