import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr00406Page({ role, notify }: PageProps) {
  const [filterDraft, setFilterDraft] = useState<number | string>('');
  const [filter, setFilter] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [accountId, setAccountId] = useState<number | string>('');
  const [reason, setReason] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/account-substitutions', role, undefined, {
      expenseResolutionId: filter,
      page,
      size: PAGE_SIZE,
    }),
    [filter, page, role],
  );

  function openCreate() {
    setResolutionId('');
    setAccountId('');
    setReason('');
    setCreating(true);
  }

  async function submit() {
    if (resolutionId === '') {
      throw new Error('대상 결의서를 선택해 주세요.');
    }
    if (accountId === '') {
      throw new Error('대체 계좌를 선택해 주세요.');
    }
    if (reason.trim() === '') {
      throw new Error('대체 사유를 입력해 주세요.');
    }
    await call('POST', '/account-substitutions', role, {
      expenseResolutionId: resolutionId,
      partnerAccountId: accountId,
      substitutionReason: reason.trim(),
    });
    notify('은행계좌 대체를 등록했습니다.');
    setCreating(false);
    setPage(0);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>계좌 대체 건수</h2>
        <Tiles items={[['전체', <Num value={data ? data.total : 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>계좌 대체 내역</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setFilter(filterDraft);
          }}
          onReset={() => {
            setFilterDraft('');
            setFilter('');
            setPage(0);
          }}
        >
          <Field label="대상 결의서">
            <LookupSelect table="expense_resolution" role={role} value={filterDraft} onChange={setFilterDraft} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>계좌 대체 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            { key: 'accountSubstitutionId', label: '은행계좌 대체 ID' },
            {
              key: 'expenseResolutionId',
              label: '대상 결의서',
              render: (row: Row) => <RefName table="expense_resolution" role={role} value={row.expenseResolutionId} />,
            },
            {
              key: 'partnerAccountId',
              label: '대체 계좌',
              render: (row: Row) => <RefName table="partner_account" role={role} value={row.partnerAccountId} />,
            },
            { key: 'substitutionReason', label: '대체 사유' },
          ]}
          rows={data ? data.items : []}
          empty="계좌 대체 내역이 없습니다."
        />
        <Pager page={data ? data.page : 0} size={PAGE_SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="은행계좌 대체 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="대상 결의서" required>
              <LookupSelect table="expense_resolution" role={role} value={resolutionId} onChange={setResolutionId} />
            </Field>
            <Field label="대체 계좌" required>
              <LookupSelect table="partner_account" role={role} value={accountId} onChange={setAccountId} />
            </Field>
            <Field label="대체 사유" required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
